function migrate(v){let out=defaultDB();out.salaries=v.salaries||[];out.cutoffs=v.cutoffs||{};out.defaultCutoff=v.defaultCutoff||24;out.records=(v.records||[]).map(r=>{let day=parse(r.date).getDay(),holidayType=r.type==='half'?'half':r.type==='full'?'full':'none',base=day>=1&&day<=5?(holidayType==='full'?0:holidayType==='half'?4:8):0;return {date:r.date,work:base+n(r.extra),annual:0,hourly:0,holidayType,holidayWork:n(r.holiday),note:r.note||'',legacy:true}});out.legacyNotice=out.records.length>0;return out}
function load(){try{let v=JSON.parse(localStorage.getItem(KEY));if(v?.version===2&&Array.isArray(v.records))return {...defaultDB(),...v}}catch(e){}try{let v=JSON.parse(localStorage.getItem(OLD));if(v?.version===1){let x=migrate(v);localStorage.setItem(KEY,JSON.stringify(x));return x}}catch(e){}return defaultDB()}
