function isDoubleMonth(key){return (db.doubleMonths||[]).includes(Number(key.split('-')[1])-1)}
function parseRate(v){let raw=String(v).trim();if(!/^\d{1,3}(?:[.,]\d{1,2})?$/.test(raw))throw Error('Zam oranını en fazla iki ondalık basamakla girin (ör. 12,75).');let number=Number(raw.replace(',','.'));if(number>100)throw Error('Zam oranı 0–100 arasında olmalı.');return number}
