let rem=extra,chunks=[];for(let r of rs.slice(0,6).reverse()){let h=Math.min(rem,n(r.work));if(h>0)chunks.push({date:r.date,h});rem-=h;if(rem<=1e-8)break}chunks.reverse();let left=a;for(let c of chunks){let aa=Math.min(c.h,left);alloc[c.date].a=aa;alloc[c.date].b=c.h-aa;left-=aa}
