   let cat=alloc[r.date]||{a:0,b:0},a=cat.a,b=cat.b,h=n(r.holidayWork),rate=hourlyAt(r.date),pool=parse(r.date).getDay()===0?'sun':'ms';
   let mode=db.fmChoices?.[fmId(iso(weekStart(r.date)),pool)]?.mode||'pay';
   let grossTotal=(a*1.25+b*1.5+h*2)*rate;
   return {...r,a,b,h,worked:n(r.work)+h,p125:a*rate*1.25,p150:b*rate*1.5,p200:h*rate*2,grossTotal,total:mode==='leave'?0:grossTotal,mode,paymentMonth:payMonth(r.date)};
