function fmBalanceOn(date){let l=fmLedger();return l.lots.filter(x=>x.available<=date&&x.expires>date).reduce((t,x)=>t+x.remaining,0)}
function fmUseOn(date){return (db.fmUses||[]).filter(x=>x.date===date).reduce((t,x)=>t+n(x.hours),0)}
