function setRecord(r){if(!validDate(r.date))throw Error('Geçerli tarih girin.');for(let k of ['work','annual','hourly','holidayWork'])if(!Number.isFinite(Number(r[k]))||Number(r[k])<0)throw Error('Süre negatif olamaz.');if(n(r.work)+n(r.holidayWork)>24||n(r.annual)>1||n(r.hourly)>24)throw Error('Günlük süre veya izin sınırı aşıldı.');if(parse(r.date).getDay()===0&&(n(r.annual)||n(r.hourly)))throw Error('Pazar günü izin girilemez.');if(parse(r.date).getDay()===0&&r.holidayType!=='none'&&n(r.work)>0)throw Error('Pazar resmî tatil mesaisini resmî tatil alanına girin.');let clean={date:r.date,work:n(r.work),annual:n(r.annual),hourly:n(r.hourly),holidayType:r.holidayType||'none',holidayWork:n(r.holidayWork),note:String(r.note||''),inputMode:r.inputMode||'net',startTime:r.startTime||'',endTime:r.endTime||'',dinner:!!r.dinner,legacy:false};db.records=db.records.filter(x=>x.date!==clean.date);if(clean.work||clean.annual||clean.hourly||clean.holidayWork||clean.holidayType!=='none'||clean.note||n(r.fmLeave))db.records.push(clean)}
function rightsYear(y){return {annual:0,carry:0,hourly:27,...(db.rights[y]||{})}}
