function navbar(){let tabs=[['home','⌂','Özet'],['entry','⊕','Kayıt'],['calendar','▦','Takvim'],['report','▥','Rapor'],['payroll','₺','Bordro'],['planner','◷','Planla'],['settings','⚙','Ayarlar']];$('tabs').innerHTML=tabs.map(([k,i,t])=>`<button class="tab ${tab===k?'active':''}" data-tab="${k}"><span class="emoji">${i}</span>${t}</button>`).join('')}
