function itemLine(r){return `<div class="dailyRecord"><div class="dailyRow"><div><strong>${DAYS[(parse(r.date).getDay()+6)%7]} · ${dayText(r.date)}</strong><div class="muted">Çalışma ${fmt(r.worked)} · Yıllık izin ${n(r.annual)} gün · Saatlik ${fmt(r.hourly)}${fmUseOn(r.date)>0?` · FM izni ${fmt(fmUseOn(r.date))}`:''}</div><div class="tiny">FM 1,25× ${fmt(r.a)} · 1,50× ${fmt(r.b)} · Resmî Tatil 2× ${fmt(r.h)}</div>${r.note?`<div class="tiny">${esc(r.note)}</div>`:''}</div><div class="actions"><button data-date="${r.date}" class="btn alt mini">Düzenle</button><button data-delete-date="${r.date}" class="btn danger mini">Sil</button></div></div></div>`}
