  if(r)html+=itemLine(r);else if(fmUseOn(date)>0)html+=`<div class="dailyRecord"><div class="dailyRow"><div><strong>${DAYS[(parse(date).getDay()+6)%7]} · ${dayText(date)}</strong><div class="muted">FM izni ${fmt(fmUseOn(date))}</div></div><div class="actions"><button data-date="${date}" class="btn alt mini">Düzenle</button><button data-delete-date="${date}" class="btn danger mini">Sil</button></div></div></div>`;
