function reportFMStatus(year){
 const {items,weeks}=calculate(),ledger=fmLedger(),endOfYear=`${year}-12-31`,asOf=iso(today)<endOfYear?iso(today):endOfYear;
 const yearItems=items.filter(x=>x.date.startsWith(year+'-'));
 const raw=yearItems.reduce((v,x)=>v+n(x.a)+n(x.b)+n(x.h),0);
 const cash=yearItems.filter(x=>x.mode!=='leave');
 const leave=yearItems.filter(x=>x.mode==='leave');
 const cashHours=cash.reduce((v,x)=>v+n(x.a)+n(x.b)+n(x.h),0);
 const cashAmount=cash.reduce((v,x)=>v+n(x.total),0);
 const leaveRawHours=leave.reduce((v,x)=>v+n(x.a)+n(x.b)+n(x.h),0);
 const leaveWeighted=leave.reduce((v,x)=>v+n(x.a)*1.25+n(x.b)*1.5+n(x.h)*2,0);
 const used=(ledger.uses||[]).filter(x=>x.date.startsWith(year+'-')&&x.date<=asOf).reduce((v,x)=>v+n(x.hours),0);
 const available=ledger.lots.reduce((v,l)=>{
   if(l.available>asOf||l.expires<=asOf)return v;
   const usedToDate=ledger.allocations.filter(a=>a.lotId===l.id).reduce((t,a)=>{
      const u=ledger.uses.find(z=>z.id===a.useId);return t+(u&&u.date<=asOf?a.minutes:0)
   },0);
   return v+Math.max(0,Math.round(l.weighted*60)-usedToDate)/60;
 },0);
 const expired=ledger.lots.filter(l=>l.paymentMonth.startsWith(year+'-')&&l.remaining>1e-8);
 const expiredHours=expired.reduce((v,l)=>v+l.remaining,0),expiredAmount=expired.reduce((v,l)=>v+l.payout,0);
 return {raw,cashHours,cashAmount,leaveRawHours,leaveWeighted,used,available,expiredHours,expiredAmount,asOf,yearItems,weeks};
}
